                    parentNode,
                    string(name[offset + 1:nextOffset]),
                    address(this), // owner
                    address(0), // resolver is cleared
                    0, // ttl
                    0, // fuses
                    0 // expiry (uses min)
                ); // reverts if not migrated
                NAME_WRAPPER.unwrap(parentNode, labelHash, address(this));
            }
            return (node, State.OWNED);
        }
    }
}
